/* Ocean Breeze Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="ocean-breeze-light"] {
  --background: rgb(243, 249, 255);
  --foreground: rgb(54, 64, 80);
  --card: rgb(255, 255, 255);
  --card-foreground: rgb(54, 64, 80);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(54, 64, 80);
  --primary: rgb(36, 196, 94);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(222, 242, 255);
  --secondary-foreground: rgb(75, 86, 102);
  --muted: rgb(245, 245, 245);
  --muted-foreground: rgb(108, 114, 126);
  --accent: rgb(209, 250, 229);
  --accent-foreground: rgb(54, 64, 80);
  --destructive: rgb(241, 68, 68);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(228, 232, 239);
  --input: rgb(228, 232, 239);
  --ring: rgb(36, 196, 94);
  --chart-1: rgb(36, 196, 94);
  --chart-2: rgb(16, 186, 130);
  --chart-3: rgb(0, 152, 106);
  --chart-4: rgb(21, 120, 88);
  --chart-5: rgb(0, 95, 69);
  --radius: 0.5rem;
  --sidebar: rgb(222, 242, 255);
  --sidebar-foreground: rgb(54, 64, 80);
  --sidebar-primary: rgb(36, 196, 94);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(209, 250, 229);
  --sidebar-accent-foreground: rgb(54, 64, 80);
  --sidebar-border: rgb(228, 232, 239);
  --sidebar-ring: rgb(36, 196, 94);
  --font-sans: DM Sans, sans-serif;
  --font-serif: Lora, serif;
  --font-mono: IBM Plex Mono, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.1;
  --shadow-blur: 8px;
  --shadow-spread: -1px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
  --shadow:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 2px 4px -2px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 4px 6px -2px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 8px 10px -2px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0px 4px 8px -1px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

/* Dark mode */
