  --background: rgb(15, 24, 43);
  --foreground: rgb(208, 212, 219);
  --card: rgb(29, 41, 61);
  --card-foreground: rgb(208, 212, 219);
  --popover: rgb(29, 41, 61);
  --popover-foreground: rgb(208, 212, 219);
  --primary: rgb(57, 209, 153);
  --primary-foreground: rgb(15, 24, 43);
  --secondary: rgb(47, 56, 72);
  --secondary-foreground: rgb(161, 161, 168);
  --muted: rgb(29, 41, 61);
  --muted-foreground: rgb(108, 114, 126);
  --accent: rgb(54, 64, 80);
  --accent-foreground: rgb(161, 161, 168);
  --destructive: rgb(241, 68, 68);
  --destructive-foreground: rgb(15, 24, 43);
  --border: rgb(75, 86, 102);
  --input: rgb(75, 86, 102);
  --ring: rgb(57, 209, 153);
  --chart-1: rgb(57, 209, 153);
  --chart-2: rgb(50, 210, 189);
  --chart-3: rgb(36, 196, 94);
  --chart-4: rgb(16, 186, 130);
  --chart-5: rgb(0, 152, 106);
  --radius: 0.5rem;
  --sidebar: rgb(29, 41, 61);
  --sidebar-foreground: rgb(208, 212, 219);
  --sidebar-primary: rgb(57, 209, 153);
  --sidebar-primary-foreground: rgb(15, 24, 43);
  --sidebar-accent: rgb(54, 64, 80);
  --sidebar-accent-foreground: rgb(161, 161, 168);
  --sidebar-border: rgb(75, 86, 102);
  --sidebar-ring: rgb(57, 209, 153);
  --font-sans: DM Sans, sans-serif;
  --font-serif: Lora, serif;
  --font-mono: IBM Plex Mono, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.1;
  --shadow-blur: 8px;
  --shadow-spread: -1px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
  --shadow:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 2px 4px -2px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 4px 6px -2px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 8px 10px -2px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0px 4px 8px -1px hsl(0 0% 0% / 0.25);
}
